<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, type Page } from './api'
interface Schedule { id: string; externalSchedule: string; orderedQuantity: string; requestedDate: string; effectiveQuantity: string; pendingQuantity: string; unconfirmedQuantity: string }
interface Item { id: string; externalItem: string; plantCode: string; materialCode: string; materialName: string; unit: string; schedules: Schedule[] }
interface Order { id: string; externalId: string; companyCode: string; purchasingOrgCode: string; supplierCode: string; sourceRevision: string; version: number; lifecycle: string; consistencyHold: boolean; items: Item[] }
interface Revision { id: string; sourceRevision: string; lifecycle: string; receivedAt: string; items: Item[] }
interface Option { id: string; name: string; code: string }
const props = defineProps<{ permissions: string[] }>()
const submitOpen = ref(false), form = ref({ scheduleId: '', quantity: '', promisedDate: '', reason: '' })
function prepare(row: Schedule) { form.value = { scheduleId: row.id, quantity: row.unconfirmedQuantity, promisedDate: row.requestedDate, reason: '' }; submitOpen.value = true }
async function submit() { await run(async () => { const current = detail.value!; await api(`/purchase-orders/${current.id}/confirmations`, 'POST', { ...form.value, sourceRevision: detail.value!.sourceRevision }, current.version); submitOpen.value = false; detail.value = await api<Order>(`/purchase-orders/${current.id}`); await load(); ElMessage.success('确认已提交；延期数量等待采购审批') }) }
const rows = ref<Order[]>([]), companies = ref<Option[]>([]), plants = ref<Option[]>([]), page = ref(1), total = ref(0), query = ref(''), companyId = ref(''), plantId = ref(''), busy = ref(false), detail = ref<Order>(), revisions = ref<Revision[]>([]), revisionPage = ref(1), revisionTotal = ref(0), open = ref(false)
async function run(fn: () => Promise<void>) { busy.value = true; try { await fn() } catch (e) { ElMessage.error(e instanceof Error ? e.message : '操作失败') } finally { busy.value = false } }
async function load() { const params = new URLSearchParams({ page: String(page.value - 1), size: '20', query: query.value }); if (companyId.value) params.set('companyId', companyId.value); if (plantId.value) params.set('plantId', plantId.value); const v = await api<Page<Order>>(`/purchase-orders?${params}`); rows.value = v.items; total.value = v.total }
async function all(path: string) { let p = 0; const values: Option[] = []; while (true) { const v = await api<Page<Option>>(`${path}?page=${p++}&size=100`); values.push(...v.items); if (!v.items.length || values.length >= v.total) break } return values }
async function history() { const v = await api<Page<Revision>>(`/purchase-orders/${detail.value!.id}/revisions?page=${revisionPage.value - 1}&size=5`); revisions.value = v.items; revisionTotal.value = v.total }
async function show(row: Order) { await run(async () => { detail.value = await api<Order>(`/purchase-orders/${row.id}`); revisionPage.value = 1; await history(); open.value = true }) }
function lines(items: Item[]) { return items.flatMap(i => i.schedules.map(s => ({ ...s, externalItem: i.externalItem, plantCode: i.plantCode, materialCode: i.materialCode, materialName: i.materialName, unit: i.unit }))) }
const states: Record<string, string> = { ACTIVE: '有效', CLOSED: '关闭', CANCELLED: '取消' }
onMounted(() => run(async () => { [companies.value, plants.value] = await Promise.all([all('/companies'), all('/plants')]); await load() }))
</script>
<template><section class="card table-card" v-loading="busy"><div class="toolbar"><el-input v-model="query" aria-label="订单号查询" placeholder="搜索采购订单号" clearable @keyup.enter="page = 1; run(load)"/><el-select v-model="companyId" aria-label="订单公司筛选" placeholder="全部授权公司" clearable><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select><el-select v-model="plantId" aria-label="订单工厂筛选" placeholder="全部授权工厂" clearable><el-option v-for="p in plants" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button @click="page = 1; run(load)">查询订单</el-button></div>
<p class="muted">订单由 ERP 同步。仅显示授权行和计划行；取消、关闭及历史版本均保留。</p><el-table :data="rows" empty-text="暂无授权采购订单"><el-table-column prop="externalId" label="采购订单号" min-width="150"/><el-table-column prop="companyCode" label="公司"/><el-table-column prop="supplierCode" label="供应商"/><el-table-column prop="purchasingOrgCode" label="采购组织"/><el-table-column prop="sourceRevision" label="来源版本"/><el-table-column label="状态"><template #default="{ row }">{{ states[row.lifecycle] }}<el-tag v-if="row.consistencyHold" type="warning">待一致性核对</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{ row }"><el-button link type="primary" @click="show(row)">订单与版本</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="run(load)"/></section>
<el-drawer v-model="open" title="采购订单与来源版本" size="85%"><template v-if="detail"><h2>{{ detail.externalId }}</h2><p>{{ detail.companyCode }} / {{ detail.purchasingOrgCode }} / {{ detail.supplierCode }} · {{ detail.sourceRevision }} · {{ states[detail.lifecycle] }}</p><el-alert v-if="detail.consistencyHold" title="此订单需要一致性核对，后续协同应保持冻结" type="warning" :closable="false"/><h3>当前授权行与计划行</h3><el-table :data="lines(detail.items)"><el-table-column prop="externalItem" label="行项目"/><el-table-column prop="plantCode" label="工厂"/><el-table-column prop="materialCode" label="物料"/><el-table-column prop="materialName" label="物料名称"/><el-table-column prop="externalSchedule" label="计划行"/><el-table-column prop="orderedQuantity" label="订购数量"/><el-table-column prop="unit" label="单位"/><el-table-column prop="requestedDate" label="要求交期"/><el-table-column prop="effectiveQuantity" label="生效数量"/><el-table-column prop="pendingQuantity" label="待批预占"/><el-table-column prop="unconfirmedQuantity" label="未确认余额"/><el-table-column v-if="props.permissions.includes('confirmation.submit')" label="确认" width="130"><template #default="{ row }"><el-button link type="primary" :disabled="detail.lifecycle !== 'ACTIVE' || detail.consistencyHold" @click="prepare(row)">部分确认</el-button></template></el-table-column></el-table>
<h3>不可变来源版本</h3><el-collapse><el-collapse-item v-for="r in revisions" :key="r.id" :name="r.id" :title="r.sourceRevision + ' · ' + states[r.lifecycle] + ' · ' + new Date(r.receivedAt).toLocaleString()"><el-table :data="lines(r.items)"><el-table-column prop="externalItem" label="行项目"/><el-table-column prop="plantCode" label="工厂"/><el-table-column prop="externalSchedule" label="计划行"/><el-table-column prop="orderedQuantity" label="订购数量"/><el-table-column prop="requestedDate" label="要求交期"/></el-table></el-collapse-item></el-collapse><el-pagination v-model:current-page="revisionPage" :page-size="5" :total="revisionTotal" layout="prev, pager, next, total" @current-change="run(history)"/></template></el-drawer><el-dialog v-model="submitOpen" title="供应商计划行部分确认" width="500px"><p class="muted">按期交期直接生效；晚于订单要求日期时预占数量，等待采购审批。</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="本次确认数量"><el-input v-model="form.quantity" aria-label="本次确认数量" placeholder="精确十进制数量"/></el-form-item><el-form-item label="确认交期"><el-input v-model="form.promisedDate" type="date" aria-label="确认交期"/></el-form-item><el-form-item label="延期原因"><el-input v-model="form.reason" type="textarea" maxlength="1000" aria-label="延期原因"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">提交订单确认</el-button></el-form></el-dialog></template>
<style scoped>.toolbar{display:flex;gap:12px;flex-wrap:wrap}.toolbar .el-input,.toolbar .el-select{max-width:220px}</style>
